#nullable enable // autogenerated

using System.Collections.Generic;
using PVZEngine;
using PVZEngine.Entities;
using PVZEngine.Properties;
using UnityEngine;

namespace MVZ2Logic.Entities
{
    [PropertyRegistryRegion(PropertyRegions.entity)]
