        public static readonly PropertyMeta<NamespaceID[]> COUNTER_TAGS = Get<NamespaceID[]>("counter_tags", obsoleteNames: "attackerTags");
        public static NamespaceID[]? GetCounterTags(this EntityDefinition enemy)
